import java.util.Scanner;

public class Main {
    static final int MAX_DEPTH = 18;
    static long[] sequence = new long[MAX_DEPTH];

    static long compute(long value, int level) {
        int count = (int)(value / sequence[level]);
        value %= sequence[level];

        if (value == 0)
            return level * count;
        return level * count + Math.min(level + compute(sequence[level] - value, level - 1), compute(value, level - 1));
    }

    public static void main(String[] args) {
        sequence[0] = 0;
        for (int i = 1; i < MAX_DEPTH; i++)
            sequence[i] = sequence[i - 1] * 10 + 1;

        Scanner scanner = new Scanner(System.in);
        while (scanner.hasNextLong()) {
            long num = scanner.nextLong();
            System.out.println(compute(num, MAX_DEPTH - 1));
        }
        scanner.close();
    }
}
